function simpleHash(key, arraySize = 10) {
  let codeSum = 0;
  for (let i = 0; i < key.length; i++) {
    codeSum += key.charCodeAt(i);
  }
  return codeSum % arraySize;
}

console.log("'Alice' 分配到的柜子号:", simpleHash('Alice'));
console.log("'Bob' 分配到的柜子号:", simpleHash('Bob'));
console.log("'Charlie' 分配到的柜子号:", simpleHash('Charlie'));
